# Load grids to verify we have the test input
import os, glob, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))

# Print the test input
task = 'task-607a9d08'
if task in G:
    print("\nTest input grid:")
    for row in G[task]:
        print(' '.join(f'{x:2d}' for x in row))
else:
    print(f"Task {task} not found in loaded grids")

import re, json

d = os.environ['RLM_SESSION_DIR']
log_path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(log_path, 'r') as f:
    lines = f.readlines()

# For each line, check if it contains demo data (not just my code)
for i, line in enumerate(lines):
    # Skip JSON metadata
    if not line.strip().startswith('{"type":"message'):
        continue

    # Get the message content
    try:
        msg = json.loads(line.strip())
        content = msg.get('message', {}).get('content', '')
        if hasattr(content, 'get'):
            content = str(content)

        # Look for actual grid data (numbers in pattern like "6 6 4 6" within "Demo pair")
        if 'Demo pair' in line or (content and 'Demo pair' in str(content)):
            # Check if this line has actual numbers (not just string 'Demo pair' in markdown)
            # Look for the pattern "Demo pair N input (WxH):\n6 6 4 6..."
            if isinstance(content, list):
                text_parts = [str(p.get('text', '')) for p in content if isinstance(p, dict)]
                text = ' '.join(text_parts)
            else:
                text = content

            if text and 'Demo pair' in text:
                # Check if there are grid numbers nearby
                if re.search(r'\d+x\d+\):\s*\d+', text) or re.search(r'\(\d+x\d+\):\n6', text):
                    print(f"Line {i} has demo-like content:")
                    if text[:800].find('6 6 4') >= 0:
                        print("Contains '6 6 4' pattern - likely demo data!")
                        print(text[:300])
                    print("---")
    except:
        pass

import re, json

d = os.environ['RLM_SESSION_DIR']
log_path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(log_path, 'r') as f:
    lines = f.readlines()

# Look for JSON messages that contain "Demo pair" followed by numbers and spaces
# The ARC evaluator sends messages with content that includes grid data
demo_messages = []
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        # Look in the 'content' field for demo pair with grid
        text_found = False
        for item in msg.get('content', []):
            if 'text' in item:
                text = item['text']
                if 'Demo pair' in text and (text.count(' ') > 10 or re.search(r'\d+x\d+', text)):
                    # Check if it's after the prompt - should have test input or demo pairs
                    if 'Test input' in text and 'Demo pair' in text:
                        demo_messages.append(msg)
                        print(f"Found demo message at line {i}")
                        print(f"Content snippet: {text[:500]}")
                        text_found = True
                        break
            if text_found:
                break
    except:
        pass

if not demo_messages:
    print("No obvious demo messages found")
